    ["Side Effects Can Include: Dizzyness, Dry Mouth, Fatigue, Lack of Appetite, Acute Radiation Poisoning, Mutation, and Death. Use as directed."] = "Side Effekter Kan Omfatte: Svimmelhed, Tør Mund, Træthed, Manglende Appetit, Akut Strålingsgift, Mutation og Død. Brug som anvist.",
    ["Side effects may include: Upset Stomach, Heartburn, and Shrinkage."] = "Side effekter kan omfatte: Mavebesvær, Halsbrand og Krympning.",
    ["Slippers of the Five Thunders , Kilt of the Five Thunders , and Pauldrons of the Five Thunders (Elemental Specialization)"] = "Tøffler af De Fem Torden , Kilt af De Fem Torden , og Skulderplader af De Fem Torden (Elementar Specialisering)",
    ["Small pieces of cloth and thread that were mysteriously drawn toward the Crusader's Loom. Apparently used when stitching holy vestaments."] = "Små stykker klæde og tråd, der mystisk blev trukket mod Korsfarerens Væv. Tilsyneladende brugt når man syr hellige messehagler.",
    ["Some call it, The Gaxe."] = "Nogle kalder den for Gøksen.",
    ["Some flames need not burn twice as bright to burn half as long."] = "Nogle flammer behøver ikke brænde dobbelt så klare for at brænde halvt så længe.",
    ["Soulforge Crown and Soulforge Embrace (Holy Specialization)"] = "Sjælesmede-krone og Sjælesmede-omfavnelse (Hellig Specialisering)",
    ["Soulforge Faceguard and Soulforge Chestguards (Protection Specialization)"] = "Sjælesmede-ansigtsbeskytter og Sjælesmede-brystbeskyttere (Beskyttelse Specialisering)",
    ["Soulforge Fists and Soulforge Cord (Holy Specialization)"] = "Sjælesmede-næver og Sjælesmede-snor (Hellig Specialisering)",
    ["Soulforge Gauntlets and Soulforge Belt Retribution Specialization)"] = "Sjælesmede-handsker og Sjælesmede-bælte Gengældelse Specialisering)",
    ["Soulforge Greathelm and Soulforge Breastplate (Retribution Specialization)"] = "Sjælesmede-storhjelm og Sjælesmede-brystplade (Gengældelse Specialisering)",
    ["Soulforge Handguards and Soulforge Waistguard Protection Specialization)"] = "Sjælesmede-Håndbeskyttere og Sjælesmede-taljebeskytter Beskyttelse Specialisering)",
    ["Soulforge Sabatons , Soulforge Legguards , and Soulforge Pauldrons (Protection Specialization)"] = "Sjælesmede-panserstøvler , Sjælesmede-benskinner , og Sjælesmede-skulderplader (Beskyttelse Specialisering)",
    ["Soulforge Treads , Soulforge Leggings , and Soulforge Epaulets (Holy Specialization)"] = "Sjælesmede-trin , Sjælesmede-benbeskyttere , og Sjælesmede-skulderstykker (Hellig Specialisering)",
    ["Soulforge Warboots , Soulforge Legplates , and Soulforge Spaulders (Retribution Specialization)"] = "Sjælesmede-krigsstøvler , Sjælesmede-benplader , og Sjælesmede-skulderstykker (Gengældelse Specialisering)",
    ["Still dripping with blood"] = "Drypper stadig af blod",
    ["Sturdy architectural techniques capable of withstanding all but the most cataclysmic disasters. A fine addition to any library's collection."] = "Kraftige arkitektoniske teknikker, der kan modstå alle undtagen de mest kataklysmiske katastrofer. En fin tilføjelse til enhver bibliotekssamling.",
    ["Tainted by the Emerald Nightmare, this splinter drains the life of its possessor."] = "Besmittet af Smaragdmaren, dræner denne splint livet fra sin besidder.",
    ["Tainted by the influence of the Burning Blade, this totem is gnarled, blackened, and scarred, but you can sense the element within. Surely someone else will be as concerned as you are with this discovery."] = "Besmittet af Brændende Klinges indflydelse, er denne totem knudret, sortnet og arret, men du kan fornemme elementet indeni. Helt sikkert vil nogen andre være lige så bekymrede som dig over denne opdagelse.",
    ["Taken from the purses of your victims and blessed by the Blood Loa."] = "Modtaget fra dine ofres pengepunge og velsignet af Blodloaerne.",
    ["Teaches you Aspect of the Falcon"] = "Lærer dig Aspekt af Falken",
    ["Teaches you Aspect of the Viper."] = "Lærer dig Aspekt af Hugorm.",
    ["Teaches you Atrophic Poison"] = "Lærer dig Atrofisk Gift",
    ["Teaches you Avenging Wrath."] = "Lærer dig Hævnens Vrede.",
    ["Teaches you Commanding Shout."] = "Lærer dig Kommanderende Råb.",
    ["Teaches you Conjure Water (Rank 8)."] = "Lærer dig Fremkald Vand (Rang 8).",
    ["Teaches you Deeper Wilds."] = "Lærer dig Dybere Vildmarken.",
    ["Teaches you Divine Steed."] = "Lærer dig Guddommelig Ganger.",
    ["Teaches you Enhanced Blessings."] = "Lærer dig Forbedrede Velsignelser.",
    ["Teaches you Enhanced Restoration."] = "Lærer dig Forbedret Genoprettelse.",
    ["Teaches you Exorcist."] = "Lærer dig Eksorcist.",
    ["Teaches you Expanded Intellect."] = "Lærer dig Udvidet Intellekt.",
    ["Teaches you Fel Armor."] = "Lærer dig Ond Rustning.",
    ["Teaches you Heart of the Lion."] = "Lærer dig Løvens Hjerte.",
    ["Teaches you Horn of Lordaeron."] = "Lærer dig Herrelandenes Horn.",
    ["Teaches you Increased Fortitude."] = "Lærer dig Øget Sejhed.",
    ["Teaches you Meathook."] = "Lærer dig Kødkrog.",
    ["Teaches you Numbing Poison"] = "Lærer dig Døvende Gift",
    ["Teaches you Occult Poison"] = "Lærer dig Okkult Gift",
    ["Teaches you Redirect."] = "Lærer dig Omdirigering.",
    ["Teaches you Revive."] = "Lærer dig Genoplive.",
    ["Teaches you Seal of Martyrdom."] = "Lærer dig Segl af Martyrium.",
    ["Teaches you Sebacious Poison"] = "Lærer dig Talgagtig Gift",
    ["Teaches you Shadowfiend."] = "Lærer dig Skyggefjende.",
    ["Teaches you Shamanistic Rage."] = "Lærer dig Shamanistisk Vrede.",
    ["Teaches you Soul Harvesting."] = "Lærer dig Sjælehøst.",
    ["Teaches you Totemic Projection."] = "Lærer dig Totemist Projektion.",
    ["Teaches you Valor of Azeroth."] = "Lærer dig Tapperhed af Azerot.",
    ["Teaches you how to craft Scarlet Augur's Vestaments."] = "Lærer dig at fremstille Blod-spåmandens Klædedragt.",
    ["Teaches you how to craft Tinker: Magnetic Displacement."] = "Lærer dig at fremstille Kedelreparatør: Magnetisk Forskydning.",
    ["Teaches you how to craft Tinker: Nitro Boosts."] = "Lærer dig at fremstille Kedelreparatør: Nitro-boostere.",
    ["Teaches you how to craft Tinker: Teleport."] = "Lærer dig at fremstille Kedelreparatør: Teleportering.",
    ["Teaches you how to craft Tinkerbox."] = "Lærer dig at fremstille Kedelreparatørkasse.",
    ["Teaches you how to craft Tinkerbox: Magnetic Displacement."] = "Lærer dig at fremstille Kedelreparatørkasse: Magnetisk Forskydning.",
    ["Teaches you how to craft Tinkerbox: Nitro Boosts."] = "Lærer dig at fremstille Kedelreparatørkasse: Nitro-boostere.",
    ["Teaches you how to craft Tinkerbox: Teleport."] = "Lærer dig at fremstille Kedelreparatørkasse: Teleportering.",
    ["Teaches you how to make an Obsidian Scope."] = "Lærer dig at fremstille et Sortglas-sigte.",
    ["Teaches you how to permanently enchant bracers to add up to 12 damage to spells."] = "Lærer dig at fortrylle armbeskyttere permanent, så de tilføjer op til 12 skade til besværgelser.",
    ["Teaches you how to permanently enchant bracers to increase Agility by 9."] = "Lærer dig at fortrylle armbeskyttere permanent, så de øger Smidighed med 9.",
    ["The Blood Loa chooses only the worthy."] = "Blodloaerne vælger kun de værdige.",
    ["The Hand of Nefarius"] = "Skurkiusens Hånd",
    ["The Hardest Core."] = "Den Hårdeste Kerne.",
    ["The Old Gods' servant Aku'mai is dead. Bashana Runetotem would be very interested to hear of this."] = "De Gamle Guders tjener Aku'maj er død. Bashana Rune-Totem ville være meget interesseret i at høre om dette.",
    ["The Old Gods' servant Aku'mai is dead. Dawnwatcher Selgorm would be very interested to hear of this."] = "De Gamle Guders tjener Aku'maj er død. Daggryvogter Selgorm ville være meget interesseret i at høre om dette.",
    ["The Sword and the Stone"] = "Sværdet og Stenen",
    ["The contents swirl and twist as if trying to escape"] = "Indholdet hvirvler og vrider sig, som om det forsøger at flygte",
    ["The craftsmanship of this cloak is stunning. It's going to look great on you until it inevitably malfunctions and bursts into flames."] = "Håndværket i denne kappe er bedøvende. Den kommer til at se fantastisk ud på dig, indtil den uundgåeligt går i stykker og slår i flammer.",
    ["The finest mojo of the Atal'ai trolls"] = "Det fineste trylleri fra Atal'aj-trolderne",
    ["The flesh from different dragon flights has been sewn together to make this belt."] = "Kødet fra forskellige drageflugter er syet sammen for at lave dette bælte.",
    ["The haft is etched with a name \"N. Sideus\""] = "Skaftet er ætset med et navn \"N. Sidøs\"",
    ["The head of the Black Dragonflight's Brood Mother"] = "Hovedet af Den Sorte Drageflugts Yngelmoder",
    ["The head shows tiny cracks."] = "Hovedet viser små revner.",
    ["The hides of several different dragon flights appear to be stitched together, comprising the top of the shoulders."] = "Huderne fra flere forskellige drageflugter ser ud til at være syet sammen og danner toppen af skuldrene.",
    ["The horn has grown more weathered and worn from use."] = "Hornet er blevet mere forvitret og slidt af brug.",
    ["The horn seems to be imbued with the light. It emanates an aura of comforting warmth."] = "Hornet synes at være gennemsyret af lyset. Det udsender en glorie af beroligende varme.",
    ["The initials A.L. are etched on the hilt."] = "Initialerne A.L. er ætset ind i hjaltet.",
    ["The inscription reads: Fer really long castin'."] = "Indskriften lyder: Fer virkelig lang kastin'.",
    ["The inscription reads: Fishin's fer sissies -Nat Pagle"] = "Indskriften lyder: Fiskeri er fer for kujoner -Nat Lommetyv",
    ["The metal is warm to the touch. The links connecting the belt together appear to be fashioned out of Elementium."] = "Metallet er varmt at tage på. Ledene, der binder bæltet sammen, ser ud til at være smedet af Elementum.",
    ["The pages are charred beyond readability. They seem to be wrapped around something."] = "Siderne er forkullet ud over enhver læselighed. De ser ud til at være indpakket om noget.",
    ["The rotating edges on this shield are surprisingly sharp. This seems just as dangerous for the bearer as it is to the attacker."] = "De roterende kanter på dette skjold er overraskende skarpe. Dette ser lige så farligt ud for bæreren som for angriberen.",
    ["The seething flames of hatred."] = "De sydende flammer af had.",
    ["The sensation you feel when wearing these bracers is not entirely pleasant."] = "Fornemmelsen, du får, når du bærer disse armbeskyttere, er ikke helt behagelig.",
    ["The simulacrum has been enchanted to mark the bearer as a friend of the Red Dragonflight."] = "Simulakrummet er blevet fortryllet til at markere bæreren som en ven af Den Røde Drageflugt.",
    ["The sound of crashing waves echo with every swing."] = "Lyden af brydende bølger genlyder med hvert hug.",
    ["The subtitle, while a bit perplexing, reads: \"A Strategic Guide to the Stars and Back.\""] = "Undertitlen, der er lidt forvirrende, lyder: \"En strategisk vejledning til Stjernerne og Ryg.\"",
    ["The symbols ' > v ^ < ' are engraved along the border."] = "Symbolerne ' > v ^ < ' er indgraveret langs kanten.",
    ["The threading is unlike anything you have ever seen. It appears metallic in origin."] = "Trådningen er ulig noget, du nogensinde har set. Den ser ud til at være af metallisk oprindelse.",
    ["The title reads \"The Brode to Nowhere\""] = "Titlen lyder: \"Vejen til Ingensteds\"",
    ["The words 'Deal With It' are etched into the side"] = "Ordene 'Forvold med det' er ætset ind i siden",
    ["These notes involve experiements and test data relating to various variations of plagues that were taken from Naxxramas."] = "Disse noter omhandler eksperimenter og testdata om forskellige variationer af plager, der blev modtagne fra Naxxrammas.",
    ["This Lost Isles currency is slowly being phased out of circulation, but it still enjoys a very favorable exchange rate throughout the Eastern Kingdoms and Kalimdor."] = "Denne valuta fra De Tabte Øer udfases langsomt af omløb, men den nyder stadig en meget gunstig vekselkurs i hele Østkongerigerne og Kalimdør.",
    ["This belt clinks faintly as you move."] = "Dette bælte klirrer svagt, når du bevæger dig.",
    ["This blade is dimensional. It appears to be fading from this plane of existence."] = "Denne klinge er dimensional. Den ser ud til at forsvinde fra dette eksistensplan.",
    ["This box of Gnomeregan Salvage could contain something useful to your profession"] = "Denne kasse med Nisseborg-bjærgning kunne indeholde noget, der er nyttigt for dit erhverv",
    ["This dagger appears weathered, yet its edge remains razor-sharp."] = "Denne dolk ser forvitret ud, men æggen forbliver barberskarp.",
    ["This heavy, curved blade bears the power of a hunting falcon. Like a kestrel, it speeds toward prey with incredible alacrity."] = "Denne tunge, buede klinge bærer kraften fra en jagende falk. Ligesom en tårnfalk skynder den sig mod byttet med utrolig hurtighed.",
    ["This heavy, curved blade bears the power of a hunting falcon. Like a peregrine, it strikes swiftly."] = "Denne tunge, buede klinge bærer kraften fra en jagende falk. Ligesom en vandrefalk slår den hurtigt til.",
    ["This item implies the existence of Manual Transmission Mechanostriders"] = "Denne genstand antyder eksistensen af Håndbog-Gearkasse-Mekanostridere",
    ["This large flat disc of elementium slag hums with latent energy."] = "Denne store, flade skive af elementium-slagg summer af skjult energi.",
    ["This letter is sealed"] = "Dette brev er forseglet",
    ["This missive bears the seal of Commander Beatrix of the Scarlet Crusade."] = "Dette budskab bærer segl fra Kommandør Beatrix fra det Blodrøde Korstog.",
    ["This once glorious trunk is now beaten and battered beyond recognition"] = "Denne engang herlige kiste er nu banket og slået uden for genkendelse",
    ["This potion has no effect until we put languages in."] = "Denne eliksir har nej effekt, indtil vi har puttet sprog i.",
    ["This processor core is somehow in worse shape than the last one you found. It's covered in sticky black goo that seems to be... squirming? Gross."] = "Denne processorkerne er på en eller anden måde i endnu værre stand end den sidste, du fandt. Den er dækket af klistret sort slim, der ser ud til at... vride sig? Ulækkert.",
    ["This tattered notebook contains schematics for a terrifying variety of destructive weaponry. Nogg would likely be very interested in this."] = "Denne slidte notesbog indeholder skemaer for en skræmmende mangfoldighed af ødelæggende våben. Nogg ville sandsynligvis være meget interesseret i dette.",
    ["This tattered notebook contains schematics for a terrifying variety of destructive weaponry. You should deliver these notes to High King Mekkatorque as soon as possible."] = "Denne slidte notesbog indeholder skemaer for en skræmmende mangfoldighed af ødelæggende våben. Du bør aflevere disse noter til Overkonge Mekkatorque så hurtigt som muligt.",
    ["This truesilver-wrought item is a furbolg symbol of peace. A sealed message is attached to it."] = "Denne genstand, smedet af sandsølv, er et pelsbolg-symbol på fred. Et forseglet budskab er fastgjort til den.",
    ["This weathered tome shows signs of scorching along its edges."] = "Denne forvitrede bog viser tegn på afbrænding langs kanterne.",
    ["Touching the box with your bare hands immediately fills you with a sense of deep disquiet... but also, a sense of creative inspiration like you've never felt before."] = "At røre kassen med dine bare hænder fylder dig straks med en følelse af dyb uro... men også med en følelse af kreativ inspiration, som du aldrig har følt før.",
    ["Treads of the Five Thunders , Legplates of the Five Thunders , and Spaulders of the Five Thunders (Enhancement DPS Specialization)"] = "Trin af De Fem Torden , Benplader af De Fem Torden , og Skulderstykker af De Fem Torden (Forstærkning SKADE-specialisering)",
    ["Typically used for reconnaissance."] = "Bruges typisk til spejding.",
    ["Unpredictability leads to both victory and death."] = "Uforudsigelighed fører både til sejr og død.",
    ["Used by Enchanters to enchant items."] = "Brugt af Fortryllere til at fortrylle genstande.",
    ["Used by Gnomish Engineers to reinforce their creations"] = "Brugt af Gnomiske Ingeniører til at forstærke deres skabelser",
    ["Used by Goblin Engineers to power their creations"] = "Brugt af Nisse-ingeniører til at give kraft til deres skabelser",
    ["Used in lost ages by trolls of the Empire of Zul to battle the Aqir."] = "Brugt i tabte tidsaldre af trolde fra Zul-imperiet til slag mod Aqir.",
    ["Used to enhance the flavor in cooking recipes."] = "Brugt til at forstærke smagen i madlavningsopskrifter.",
    ["Virtuous Cowl and Virtuous Gown (Shadow Specialization)"] = "Dydig Hætte og Dydig Kjole (Skygge-specialisering)",
    ["Virtuous Crown and Virtuous Robe (Healer Specialization)"] = "Dydig Krone og Dydig Kappe (Helbreder-specialisering)",
    ["Virtuous Hands and Virtuous Cord Shadow Specialization)"] = "Dydig Hænder og Dydig Snor Skygge-specialisering)",
    ["Virtuous Mitts and Virtuous Belt Healer Specialization)"] = "Dydig Vanter og Dydig Bælte Helbreder-specialisering)",
    ["Virtuous Sandals , Virtuous Skirt , and Virtuous Mantle (Healer Specialization)"] = "Dydig Sandaler , Dydig Nederdel og Dydig Skulderkappe (Helbreder-specialisering)",
    ["Virtuous Slippers , Virtuous Leggings , and Virtuous Epaulets (Shadow Specialization)"] = "Dydige Tøffler , Dydige Benbeskyttere , og Dydige Skulderstykker (Skyggespecialisering)",
    ["Water has made the ink run beyond repair. The pages seem to be wrapped around something."] = "Vand har fået blækket til at løbe ud over alt håb om reparation. Siderne ser ud til at være indpakket om noget.",
    ["Weak magic emanates from the scroll. It may have enough to revitalize the one who wrote it."] = "Svag magi udstråler fra rullen. Den har måske nok til at genoplive den, der skrev den.",
    ["Wearing these bracers makes the hair stand up on the back of your neck, as if someone is standing right behind you."] = "Når du bærer disse armbeskyttere, rejser håret sig i nakken på dig, som om nogen står lige bag dig.",
    ["What does a poor undead got do around here to reach Exalted?"] = "Hvad skal en stakkels udød dog gøre her omkring for at nå Ophøjet?",
    ["Woe to those who oppose."] = "Elendighed over dem, der modsætter sig.",
    ["Yesterday's shackles are today's fashion."] = "Gårsdagens lænker er dagens mode.",
    ["You are pretty sure these aren't made from animal skin."] = "Du er ret sikker på, at disse ikke er lavet af dyrs hud.",
    ["You can faintly hear distant screaming when handling this object."] = "Du kan svagt høre fjerne skrig, når du håndterer dette objekt.",
    ["You feel drawn to battle as you gaze upon the potion's red allure..."] = "Du føler dig draget mod slag, mens du stirrer på eliksirens røde forlokkelse...",
    ["You're not entirely certain, but you're pretty sure that \"clamweaving\" isn't a real thing."] = "Du er ikke helt sikker, men du er ret sikker på, at \"klamvævning\" ikke er en rigtig ting.",
    ["You've been told this is a stick of legends."] = "Du har fået at vide, at dette er en pind af legender.",
}
ns.ItemDescs = ns.ItemDescs or {}
for en, da in pairs(names) do
    if ns.ItemDescs[en] == nil then ns.ItemDescs[en] = da end
end
